#!/usr/bin/env bash
# Wires a module generated by `dotnet new modulith-module` into the solution. The template's post-action runs it from the solution
# root; run it by hand with --name and --prefix to repeat a step after a failure.
#
# Usage: bash build/scripts/add-module.sh [--name NAME] [--prefix PREFIX]   (from the solution root)
#   Without arguments it reads the marker .modulith-module in the current directory (line 1 the module name, line 2 the project
#   prefix) and deletes it when it finishes or cleans up. --name and --prefix override the marker values, so a manual re-run needs
#   no marker. Contracts are not a flag: the wiring detects src/Modules/{Name}/{Prefix}.Modules.{Name}.Contracts on disk.
#
# When every edit is made it also runs, from the solution root: dotnet tool restore, dotnet restore (writes the new projects'
#   packages.lock.json, and gives them the assets file dotnet ef needs), dotnet ef migrations add Create{Name}Schema and dotnet build
#   --no-restore -c Release, then lists what to commit.
#   The dotnet executable is $ADD_MODULE_DOTNET (default dotnet). A skipped edit means none of them runs: the commands are printed instead.
#
# Exit codes: 0 done, 1 a skipped edit or a failed step (the message says which; a skipped edit prints 'add by hand: <file>: <line>'
#   for each line to add yourself and 'then run: <command>' for the four commands, the other edits are done; a failed command stops
#   the script, prints itself and the later ones as 'then run: <command>' and leaves the edits in place, the module is wired then, so
#   run the printed commands by hand), 2 invalid input (nothing was wired; for an invalid name or a wrong prefix the files the engine just
#   wrote are removed again when the marker is present, a run with flags only and no marker changes nothing, and for a module that is
#   already wired nothing at all is changed).
#   A run that stops midway through the edits leaves the module unregistered in Program.cs (that edit comes last), so running it
#   again finishes.
#
# Source-safe: the tests source this file to call its functions; main runs only when it is executed.
set -euo pipefail

marker=".modulith-module"

# die MESSAGE [CODE]: prints the message only (the code is the exit status, not part of the text).
die() {
  echo "add-module: $1" >&2
  exit "${2:-1}"
}

# trim VALUE: prints VALUE without a trailing CR or surrounding whitespace.
trim() {
  local value="${1%$'\r'}"
  value="${value#"${value%%[![:space:]]*}"}"
  value="${value%"${value##*[![:space:]]}"}"
  printf '%s' "$value"
}

# kebab_case NAME: the rule of DocumentPaths.KebabCase (tests/TemplateName.ArchitectureTests): '.' becomes '-', a capital after the
# first character is preceded by '-' unless the previous output character is already '-', everything lower case, digits do not split.
#   LeaveManagement -> leave-management, HRPayroll -> h-r-payroll, Billing2 -> billing2, Application.Common -> application-common
kebab_case() {
  local name="$1" out="" character index
  for ((index = 0; index < ${#name}; index++)); do
    character="${name:index:1}"
    if [[ "$character" == "." ]]; then
      out+="-"
    elif [[ "$character" == [[:upper:]] && -n "$out" && "${out: -1}" != "-" ]]; then
      out+="-$character"
    else
      out+="$character"
    fi
  done
  printf '%s\n' "$out" | tr 'A-Z' 'a-z'
}

# validate_name NAME: returns 0 for a module name (a capital, then letters and digits), otherwise prints why and returns 2.
validate_name() {
  local LC_ALL=C
  if [[ "${1-}" =~ ^[A-Z][A-Za-z0-9]*$ ]]; then
    return 0
  fi
  echo "add-module: '${1-}' is not a valid module name: use PascalCase letters and digits only, starting with a capital (for example LeaveManagement)." >&2
  return 2
}

# validate_prefix PREFIX: returns 0 for a project prefix (dotted identifiers such as Acme.Shop), otherwise prints why and returns 2.
validate_prefix() {
  local LC_ALL=C
  if [[ "${1-}" =~ ^[A-Za-z_][A-Za-z0-9_.]*$ ]]; then
    return 0
  fi
  echo "add-module: '${1-}' is not a valid project prefix (letters, digits, '_' and '.', for example Acme.Shop)." >&2
  return 2
}

# is_wired NAME: returns 0 when the Program.cs of ANY host folder (src/Host/*/Program.cs, whatever the prefix) registers
# Add{NAME}Module(, compared case-insensitively (a case-insensitive file system treats 'audit' and 'Audit' as one folder, and a wrong
# prefix must not hide a registered module). awk, not grep -i -F, which aborts on some Git Bash builds. NAME must hold no backslash.
is_wired() {
  local -a programs=()
  local candidate
  for candidate in src/Host/*/Program.cs; do
    [[ -f "$candidate" ]] && programs+=("$candidate")
  done
  ((${#programs[@]} > 0)) || return 1
  awk -v pattern="Add${1-}Module(" 'index(tolower($0), tolower(pattern)) { found = 1; exit } END { exit !found }' "${programs[@]}"
}

# has_using NAME: returns 0 when the Program.cs of any host has a line 'using <anything>.Modules.NAME;' (case-insensitive, whatever
# the prefix): the module is at least half wired, because the using is the first edit and the registration the last. awk for the
# same reason as in is_wired.
has_using() {
  local -a programs=()
  local candidate
  for candidate in src/Host/*/Program.cs; do
    [[ -f "$candidate" ]] && programs+=("$candidate")
  done
  ((${#programs[@]} > 0)) || return 1
  awk -v name="${1-}" '
    BEGIN { suffix = tolower(".Modules." name ";") }
    {
      line = tolower($0)
      sub(/\r$/, "", line)
      sub(/^[ \t]+/, "", line)
      sub(/[ \t]+$/, "", line)
      if (substr(line, 1, 6) == "using " && length(line) > length(suffix) + 6 && substr(line, length(line) - length(suffix) + 1) == suffix) { found = 1; exit }
    }
    END { exit !found }' "${programs[@]}"
}

# remove_generated NAME PREFIX: removes exactly what the engine wrote for the module: the directories
# src/Modules/NAME/PREFIX.Modules.NAME and src/Modules/NAME/PREFIX.Modules.NAME.Contracts, src/Modules/NAME itself when that is empty
# afterwards, docs/modules/NAME.md (never the kebab-case page: the engine does not write it) and the marker. It runs only while the
# marker exists, which is the proof that the engine has just written those files: a run with flags only (no marker) changes nothing,
# so a mistyped prefix cannot reach the files of a module added by hand. It also refuses (changes nothing, prints why and returns 1)
# for a module that any host's Program.cs already registers or already has a 'using ....Modules.NAME;' line for (a run that stopped
# midway: the files on disk are the module's, and a re-run with a mistyped prefix must not delete them), and for a name that could
# point outside those paths (empty, leading '.', a slash). Returns 0 only when it removed the files.
remove_generated() {
  local name="${1-}" prefix="${2-}"
  if [[ ! -f "$marker" ]]; then
    echo "add-module: no $marker: the files are not fresh from the template, so none was removed." >&2
    return 1
  fi
  if [[ -z "$name" || "$name" == .* || "$name" == *[/\\]* ]]; then
    echo "add-module: '$name' could point outside the module folders: leaving the files alone." >&2
    rm -f -- "$marker"
    return 1
  fi
  if is_wired "$name"; then
    echo "add-module: '$name' is already registered in a src/Host/*/Program.cs: leaving its files alone." >&2
    return 1
  fi
  if has_using "$name"; then
    echo "add-module: a src/Host/*/Program.cs already has 'using ${prefix:-PREFIX}.Modules.$name;' (or the same under another prefix): the module is half wired, leaving its files alone. Run add-module.sh --name $name --prefix <the right prefix> to finish it." >&2
    return 1
  fi
  if ! validate_prefix "$prefix" > /dev/null 2>&1; then
    echo "add-module: '$prefix' is not a valid project prefix: leaving the files alone." >&2
    rm -f -- "$marker"
    return 1
  fi
  rm -rf -- "src/Modules/$name/$prefix.Modules.$name" "src/Modules/$name/$prefix.Modules.$name.Contracts"
  rmdir -- "src/Modules/$name" 2> /dev/null || true
  rm -f -- "docs/modules/$name.md" "$marker"
}

# --- edits at the anchors ------------------------------------------------------------------------------------------------------------
# One awk call per edit, with no GNU extension: it reads the whole file first and only then writes the result back to the same file
# (so the file keeps its mode), and it writes nothing when the anchor is missing or the edit is already there. The values travel
# through the environment because awk -v would interpret backslashes. LC_ALL=C keeps every byte as it is (UTF-8 text included).
# Exit status of the awk call: 0 changed, 3 anchor not found, 4 already present (nothing written), anything else a real failure.

anchors_list="build/scripts/module-anchors.txt"
skipped=()
current_name="NAME" # the real values are set by edit_all, for the messages
current_prefix="PREFIX"

# The awk program. MODULITH_MODE: lines (insert the lines of MODULITH_TEXT before the first line equal to / containing MODULITH_ANCHOR,
# per MODULITH_MATCH, copying that line's indentation and line ending), inline (insert MODULITH_TEXT right before the anchor text on
# its line) or scopes (append |MODULITH_CHECK to the value of the ALLOWED_SCOPES="..." line). MODULITH_CHECK is what tells the edit is
# already there. MODULITH_FINAL_NEWLINE tells whether the file ends with a newline; the end state is kept.
read -r -d '' awk_program <<'AWK' || true
function trim(s) {
  sub(/\r$/, "", s)
  sub(/^[ \t]+/, "", s)
  sub(/[ \t]+$/, "", s)
  return s
}
function emit(s) {
  if (written > 0) printf "\n" > target
  printf "%s", s > target
  written++
}
BEGIN {
  # Git Bash's gawk reads in text mode and would drop every CR of a CRLF file; BINMODE keeps the bytes (other awks ignore the variable).
  BINMODE = 3
  mode = ENVIRON["MODULITH_MODE"]
  anchor = ENVIRON["MODULITH_ANCHOR"]
  text = ENVIRON["MODULITH_TEXT"]
  check = ENVIRON["MODULITH_CHECK"]
  match_mode = ENVIRON["MODULITH_MATCH"]
  final_newline = (ENVIRON["MODULITH_FINAL_NEWLINE"] == "1")
  target = ARGV[1]
}
{ rows[NR] = $0 }
END {
  found = 0
  if (mode == "lines") {
    count = split(text, ins, "\n")
    first = trim(ins[1])
    for (i = 1; i <= NR; i++) {
      t = trim(rows[i])
      if (t == first) exit 4
      if (found == 0) {
        if (match_mode == "contains") {
          if (index(rows[i], anchor) > 0) found = i
        } else if (t == anchor) {
          found = i
        }
      }
    }
    if (found == 0) exit 3
    line_end = ""
    if (rows[found] ~ /\r$/) line_end = "\r"
    else if (found == NR && !final_newline && found > 1 && rows[found - 1] ~ /\r$/) line_end = "\r"
    match(rows[found], /^[ \t]*/)
    indent = substr(rows[found], 1, RLENGTH)
    for (i = 1; i <= NR; i++) {
      if (i == found) for (j = 1; j <= count; j++) emit(indent ins[j] line_end)
      emit(rows[i])
    }
  } else if (mode == "inline") {
    for (i = 1; i <= NR; i++) {
      position = index(rows[i], anchor)
      if (position > 0) { found = i; break }
    }
    if (found == 0) exit 3
    if (index(rows[found], check) > 0) exit 4
    rows[found] = substr(rows[found], 1, position - 1) text substr(rows[found], position)
    for (i = 1; i <= NR; i++) emit(rows[i])
  } else if (mode == "scopes") {
    for (i = 1; i <= NR; i++) {
      if (substr(rows[i], 1, length(anchor)) == anchor) { found = i; break }
    }
    if (found == 0) exit 3
    closing = 0
    for (k = length(rows[found]); k > length(anchor); k--) {
      if (substr(rows[found], k, 1) == "\"") { closing = k; break }
    }
    if (closing == 0) exit 3
    count = split(substr(rows[found], length(anchor) + 1, closing - length(anchor) - 1), parts, "|")
    for (k = 1; k <= count; k++) if (parts[k] == check) exit 4
    rows[found] = substr(rows[found], 1, closing - 1) "|" check substr(rows[found], closing)
    for (i = 1; i <= NR; i++) emit(rows[i])
  } else {
    exit 2
  }
  if (final_newline) printf "\n" > target
  close(target)
  exit 0
}
AWK

# run_awk FILE MODE ANCHOR TEXT CHECK MATCH: runs the program above on FILE; returns its exit status (see above).
run_awk() {
  local file="$1" content="" final=0 status=0
  IFS= read -r -d '' content < "$file" || true
  [[ "$content" == *$'\n' ]] && final=1
  LC_ALL=C MODULITH_MODE="$2" MODULITH_ANCHOR="$3" MODULITH_TEXT="$4" MODULITH_CHECK="$5" MODULITH_MATCH="$6" MODULITH_FINAL_NEWLINE="$final" \
    awk "$awk_program" "$file" || status=$?
  return "$status"
}

# after_edit FILE STATUS DESCRIPTION...: a missing anchor (status 3) or file puts each DESCRIPTION on the skipped list; 0 and 4
# (already there) are fine; any other status stops the script, because the file may be half written.
after_edit() {
  local file="$1" status="$2" entry
  shift 2
  case "$status" in
    0 | 4) ;;
    3)
      for entry in "$@"; do skipped+=("$file: $entry"); done
      ;;
    *) die "editing $file failed (awk status $status); check it with git diff, then run add-module.sh --name $current_name --prefix $current_prefix again." 1 ;;
  esac
}

# insert_lines FILE MATCH ANCHOR LINE...: inserts the LINEs before the first line of FILE that equals (MATCH equals) or contains
# (MATCH contains) ANCHOR. A LINE's own leading blanks are kept after the anchor line's indentation, so a block can nest. A missing
# file or anchor puts '<file>: <line>' for each LINE on the skipped list.
insert_lines() {
  local file="$1" match="$2" anchor="$3" joined line status=0
  shift 3
  local -a wanted=("$@")
  if [[ ! -f "$file" ]]; then
    after_edit "$file" 3 "${wanted[@]}"
    return 0
  fi
  joined="${wanted[0]}"
  for line in "${wanted[@]:1}"; do joined+=$'\n'"$line"; done
  run_awk "$file" lines "$anchor" "$joined" "" "$match" || status=$?
  after_edit "$file" "$status" "${wanted[@]}"
}

# load_anchor KEY: sets anchor_file and anchor_text from module-anchors.txt; returns 1 when the list or the key is missing.
anchor_file=""
anchor_text=""
load_anchor() {
  local row_key row_file row_text
  anchor_file=""
  anchor_text=""
  [[ -f "$anchors_list" ]] || return 1
  while IFS='|' read -r row_key row_file row_text || [[ -n "$row_key" ]]; do
    if [[ "$row_key" == "$1" ]]; then
      anchor_file="${row_file%$'\r'}"
      row_text="${row_text%$'\r'}"
      row_text="${row_text#"${row_text%%[![:space:]]*}"}"
      anchor_text="${row_text%"${row_text##*[![:space:]]}"}"
      return 0
    fi
  done < "$anchors_list"
  return 1
}

# insert_before_anchor KEY LINE...: inserts the LINEs immediately before the anchor line of KEY (so the anchor stays last and a later
# module goes after an earlier one). Does nothing when the first LINE is already in the file; records '<file>: <line>' on the skipped
# list for each LINE when the anchor (or its file) is missing.
insert_before_anchor() {
  local key="$1"
  shift
  if ! load_anchor "$key"; then
    after_edit "anchors:$key" 3 "$@"
    return 0
  fi
  insert_lines "$anchor_file" equals "$anchor_text" "$@"
}

# insert_inline_before_anchor KEY TEXT CHECK DESCRIPTION: inserts TEXT right before the anchor text on its line (for an anchor that
# ends a table row); does nothing when that row already contains CHECK. A missing anchor records DESCRIPTION.
insert_inline_before_anchor() {
  local key="$1" text="$2" check="$3" description="$4" status=0
  if ! load_anchor "$key"; then
    after_edit "anchors:$key" 3 "$description"
    return 0
  fi
  if [[ ! -f "$anchor_file" ]]; then
    after_edit "$anchor_file" 3 "$description"
    return 0
  fi
  run_awk "$anchor_file" inline "$anchor_text" "$text" "$check" "" || status=$?
  after_edit "$anchor_file" "$status" "$description"
}

# edit_commit_scopes SCOPE: appends |SCOPE to ALLOWED_SCOPES in check-commit-msg.sh.
edit_commit_scopes() {
  local file="build/scripts/check-commit-msg.sh" status=0
  if [[ ! -f "$file" ]]; then
    after_edit "$file" 3 "add |$1 to the ALLOWED_SCOPES list"
    return 0
  fi
  run_awk "$file" scopes 'ALLOWED_SCOPES="' "" "$1" "" || status=$?
  after_edit "$file" "$status" "add |$1 to the ALLOWED_SCOPES list"
}

# edit_all NAME PREFIX: applies every edit of the wiring table. Contracts lines are written when the Contracts project folder exists.
# The Program.cs registration comes LAST: is_wired treats a module registered there as existing, so a run that stops midway leaves the
# module unwired and a re-run finishes the remaining (idempotent) edits.
edit_all() {
  local m="$1" p="$2" k mod con contracts=0
  current_name="$m"
  current_prefix="$p"
  k="$(kebab_case "$m")"
  mod="$p.Modules.$m"
  con="$p.Modules.$m.Contracts"
  [[ -d "src/Modules/$m/$con" ]] && contracts=1

  insert_before_anchor program-usings "using $mod;"
  insert_before_anchor program-endpoints "api.Map${m}Endpoints();"

  local key prefix_path ref
  for key in api-references unit-references arch-references integration-references; do
    # The host project sits two levels below the root (..\..\Modules), a test project reaches src from there (..\..\src\Modules).
    if [[ "$key" == api-references ]]; then prefix_path='..\..\Modules'; else prefix_path='..\..\src\Modules'; fi
    ref="<ProjectReference Include=\"$prefix_path\\$m\\$mod\\$mod.csproj\" />"
    if ((contracts)); then
      insert_before_anchor "$key" "$ref" "<ProjectReference Include=\"$prefix_path\\$m\\$con\\$con.csproj\" />"
    else
      insert_before_anchor "$key" "$ref"
    fi
  done

  if ((contracts)); then
    insert_before_anchor slnx-modules "<Folder Name=\"/src/Modules/$m/\">" \
      "  <Project Path=\"src/Modules/$m/$mod/$mod.csproj\" />" "  <Project Path=\"src/Modules/$m/$con/$con.csproj\" />" "</Folder>"
    insert_before_anchor docker-copies \
      "COPY src/Modules/$m/$mod/$mod.csproj src/Modules/$m/$mod/packages.lock.json src/Modules/$m/$mod/" \
      "COPY src/Modules/$m/$con/$con.csproj src/Modules/$m/$con/packages.lock.json src/Modules/$m/$con/"
  else
    insert_before_anchor slnx-modules "<Folder Name=\"/src/Modules/$m/\">" "  <Project Path=\"src/Modules/$m/$mod/$mod.csproj\" />" "</Folder>"
    insert_before_anchor docker-copies "COPY src/Modules/$m/$mod/$mod.csproj src/Modules/$m/$mod/packages.lock.json src/Modules/$m/$mod/"
  fi

  insert_before_anchor assemblies-usings "using $mod;" "using $mod.Resources;"
  insert_before_anchor assemblies-modules "typeof(${m}Module).Assembly,"
  if ((contracts)); then
    insert_before_anchor assemblies-contracts "Assembly.Load(\"$con\"),"
  fi
  insert_before_anchor assemblies-errors "typeof(${m}ErrorMessages),"

  insert_inline_before_anchor contributing-scopes ", \`$k\`" "\`$k\`" "add \`$k\` to the Modules row of the scopes table"
  insert_lines "docs/README.md" contains "modules/_template.md" "| [\`modules/$k.md\`](modules/$k.md) | $m: new module (describe it) |"
  edit_commit_scopes "$k"

  insert_before_anchor program-registrations "builder.Services.Add${m}Module(builder.Configuration);"
}

# --- after the edits: migration, restore, build ------------------------------------------------------------------------------------

steps=()
step_labels=("dotnet tool restore" "dotnet restore" "dotnet ef migrations add" "dotnet build")

# module_steps NAME PREFIX: sets steps to the arguments of the four dotnet commands, in order (no value holds a space: the name and the
# prefix are validated before anything runs). The plain restore comes BEFORE the migration: dotnet ef restores nothing itself and
# fails with NETSDK1004 ("Assets file ... not found") for the new, not yet restored module project (found by running the real tree).
module_steps() {
  local m="$1" p="$2"
  steps=(
    "tool restore"
    "restore"
    "ef migrations add Create${m}Schema --project src/Modules/$m/$p.Modules.$m --startup-project src/Host/$p.Api --context ${m}DbContext --output-dir Infrastructure/Persistence/Migrations"
    "build --no-restore -c Release"
  )
}

# list_steps FROM: prints the commands from index FROM on as 'then run: dotnet ...' lines (to run by hand).
list_steps() {
  local index
  for ((index = $1; index < ${#steps[@]}; index++)); do
    echo "add-module: then run: dotnet ${steps[index]}" >&2
  done
}

# finish_module NAME PREFIX: runs the four commands in order from the solution root; the first failure stops it (returns 1, naming the
# step and listing it with the later ones). The plain restore writes the new projects' packages.lock.json (the Dockerfile COPY lines
# and the locked-mode restore of CI need them committed) and the assets files the migration needs. Then lists what to commit.
finish_module() {
  local dotnet="${ADD_MODULE_DOTNET:-dotnet}" index status log
  local -a argv
  module_steps "$1" "$2"
  # The output of the dotnet commands goes to a log file, so the script prints only its own few lines (a failure prints the last lines
  # of the log and keeps the file, a success deletes it). This also matters under the template engine: a post-action that redirects
  # the script's output reads it only after the script ends, and the script blocked in a write for ever once more than the pipe's
  # buffer (a few KB) of build output had been written (seen on the real tree). The template's post-action does not redirect.
  log="$(mktemp "${TMPDIR:-/tmp}/add-module.XXXXXX")"
  for index in "${!steps[@]}"; do
    echo "add-module: running ${step_labels[index]}"
    read -r -a argv <<< "${steps[index]}"
    status=0
    "$dotnet" "${argv[@]}" > "$log" 2>&1 || status=$?
    if ((status != 0)); then
      echo "add-module: step '${step_labels[index]}' failed (exit status $status); the later steps did not run. The module is wired: fix the cause, then run by hand from the solution root:" >&2
      list_steps "$index"
      echo "add-module: the last lines of its output (all of it is in $log):" >&2
      tail -n 12 "$log" | cut -c1-200 >&2
      return 1
    fi
  done
  rm -f -- "$log"

  echo "add-module: commit these:"
  if git rev-parse --is-inside-work-tree > /dev/null 2>&1; then
    git status --short
    # A new folder is listed as one line above, so the new packages.lock.json files (the Dockerfile COPY lines and the locked-mode
    # restore of CI need them) are named one by one; a tracked one that changed is in the list above already.
    git ls-files --others --exclude-standard -- '*packages.lock.json'
  else
    echo "add-module: this is not a git repository: commit the new module folders (src/Modules/$1, docs/modules/$(kebab_case "$1").md), the packages.lock.json files they gained, and the edited shared files."
  fi
  return 0
}

main() {
  local name="" prefix="" line_one="" line_two=""

  while (($# > 0)); do
    case "$1" in
      --name)
        (($# >= 2)) || die "--name needs a value" 2
        name="$2"
        shift 2
        ;;
      --prefix)
        (($# >= 2)) || die "--prefix needs a value" 2
        prefix="$2"
        shift 2
        ;;
      *)
        die "unknown argument '$1' (usage: add-module.sh [--name NAME] [--prefix PREFIX])" 2
        ;;
    esac
  done

  # 1. The marker supplies what the flags did not.
  if [[ -z "$name" || -z "$prefix" ]]; then
    [[ -f "$marker" ]] || die "no $marker in $(pwd) and no --name and --prefix given: run it from the solution root of a generated project." 2
    { IFS= read -r line_one || true; IFS= read -r line_two || true; } < "$marker"
    [[ -n "$name" ]] || name="$(trim "$line_one")"
    [[ -n "$prefix" ]] || prefix="$(trim "$line_two")"
  fi
  [[ -n "$name" ]] || die "no module name: line 1 of $marker is empty and --name was not given." 2
  [[ -n "$prefix" ]] || die "no project prefix: line 2 of $marker is empty and --prefix was not given." 2

  # 2. The name becomes folder, namespace and type names, so it is checked before anything is wired; an invalid one is cleaned up.
  if ! validate_name "$name"; then
    remove_generated "$name" "$prefix" || true # prints why and changes nothing when it refuses (no marker, a registered name)
    exit 2
  fi

  # 3. Already wired under ANY host (not only the prefix given): the files on disk belong to that module, so nothing at all is
  #    touched, the marker included.
  if is_wired "$name"; then
    die "module '$name' (--name $name --prefix $prefix) is already wired in a src/Host/*/Program.cs: nothing was changed." 2
  fi

  # 4. The prefix must be the project's own: no edit is made when the host project does not exist.
  if ! validate_prefix "$prefix" || [[ ! -d "src/Host/$prefix.Api" ]]; then
    echo "add-module: src/Host/$prefix.Api does not exist: '$prefix' is not this project's prefix." >&2
    if remove_generated "$name" "$prefix"; then
      echo "add-module: the generated module files are removed; run the template again with the right prefix." >&2
    fi
    exit 2
  fi

  # 5. The documentation page keeps the kebab-case name every documentation test expects.
  local kebab source target
  kebab="$(kebab_case "$name")"
  source="docs/modules/$name.md"
  target="docs/modules/$kebab.md"
  if [[ ! -f "$source" && -f "$target" ]]; then
    : # A re-run after a run that stopped midway: the page was renamed already.
  elif [[ ! -f "$source" ]]; then
    die "$source is missing: the template did not generate the module's documentation page." 1
  elif [[ -e "$target" && ! "$source" -ef "$target" ]]; then
    die "$target already exists: not overwriting it. Move or remove it, then run add-module.sh --name $name --prefix $prefix again." 2
  elif [[ "$source" -ef "$target" ]]; then
    # A case-insensitive file system sees both names as one file: rename through a temporary name.
    mv -- "$source" "$target.tmp"
    mv -- "$target.tmp" "$target"
  else
    mv -- "$source" "$target"
  fi

  # 6. The edits in the shared files (see edit_all for the order). A skipped edit does not stop the others.
  edit_all "$name" "$prefix"

  # 7. The marker goes on every outcome from here: the module is wired (or its leftovers are listed), so a re-run needs the flags.
  rm -f -- "$marker"
  if ((${#skipped[@]} > 0)); then
    local entry
    for entry in "${skipped[@]}"; do
      echo "add-module: add by hand: $entry" >&2
    done
    # Migrating and building a half-wired solution would fail for the wrong reason, so the commands are only listed.
    module_steps "$name" "$prefix"
    list_steps 0
    exit 1
  fi
  echo "add-module: '$name' is wired into the shared files."

  # 8. Migration, restore, build, then what to commit.
  finish_module "$name" "$prefix" || exit 1
}

if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then
  main "$@"
fi
